"""Author only PRE_A1-U05, including its eight-task checkpoint."""
import json,copy,re,sys
from pathlib import Path
ROOT=Path(__file__).resolve().parents[4]
KIT=ROOT/'plans/daily-practice-authoring'
OUT=Path(__file__).parent/'packages/PRE_A1'
level=json.loads((KIT/'levels/PRE_A1.plan.json').read_text())['level']
plan=level['units'][4]
W={}
for source in [OUT/'PRE_A1-U04.v1.json',OUT/'PRE_A1-U03.v1.json',OUT/'PRE_A1-U02.v1.json',KIT/'examples/PRE_A1-U01.v2.json']:
 for s in json.loads(source.read_text())['sessions']:
  for w in s['vocabulary']:W.setdefault(w['id'],copy.deepcopy(w))
for w in W.values():
 if 'example' not in w:w['example']=dict(fr=w['fr'],ru=w['ru'][0],transcription_ru=w['transcription_ru'])
OLD=set(W);FIRST={};S=[]
U='PRE_A1.U05.UNDERSTAND';A='PRE_A1.U05.APPLY'
OBJECTIVES={o['id']:o for u in level['units'] for o in u['objectives']}

def ru(t): return dict(text=t,text_lang='ru')

def fr(t,p): return dict(text=t,text_lang='fr',transcription_ru=p)

def ex(f,r,p): return dict(fr=f,ru=r,transcription_ru=p)

def sound(f,p): return dict(text=f,transcription_ru=p,lang='fr-FR',asset_id=None)

def wc(w): return fr(W[w]['fr'],W[w]['transcription_ru'])

def fb(g,b): return dict(correct=g,incorrect=b)

def opts(v): return [dict(id=f'c{i}',**(ru(t) if isinstance(t,str) else t)) for i,t in enumerate(v)]

def rev(i,p,cs,a,g,b): return dict(id=i,type='single_choice',instruction='Выберите один ответ.',prompt=p,choices=opts(cs),correct_choice_id=f'c{a}',feedback=fb(g,b))

def start(n,d,vs):
 p=plan['sessions'][n-1]; s={k:copy.deepcopy(p[k]) for k in ['id','title','order','kind','prerequisite_ids']}
 s.update(version=1,level='PRE_A1',unit_id=plan['id'],description=d,duration_minutes=6,objectives=copy.deepcopy(plan['objectives']),skills=[],vocabulary=[copy.deepcopy(W[w]) for w in vs],tasks=[],introductions=[]); S.append(s); return s

def base(s,sk,gs,vs,av,ins,p,g,b):
 for o in gs:
  if o not in [x['id'] for x in s['objectives']]: s['objectives'].append(copy.deepcopy(OBJECTIVES[o]))
 if sk not in s['skills']: s['skills'].append(sk)
 t=dict(id=f'Q{len(s["tasks"])+1:02}',instruction=ins,prompt=p,feedback=fb(g,b),objective_ids=gs,skill=sk,vocabulary_ids=vs,assessed_vocabulary_ids=av); s['tasks'].append(t); return t

def choose(s,sk,gs,vs,av,ins,p,cs,a,g,b):
 t=base(s,sk,gs,vs,av,ins,p,g,b); t.update(type='single_choice',choices=opts(cs),correct_choice_id=f'c{a}'); return t

def listen(s,gs,vs,av,q,f,p,cs,a,g,b):
 return choose(s,'listening',gs,vs,av,'Прослушайте и выберите ответ.',dict(**ru(q),audio=sound(f,p)),cs,a,g,b)

def intro(s,n,t,vs,ns=(),au=None):
 i=dict(id=f'I{len(s["introductions"])+1:02}',before_task_id=f'Q{n:02}',text=t,vocabulary_ids=vs)
 if ns:i['pronunciation_notes']=[dict(fr=f,transcription_ru=p) for f,p in ns]
 if au:i['audio']=sound(*au)
 s['introductions'].append(i)

def pairs(s,gs,rows,g,b):
 vs=[w for w,r in rows]; t=base(s,'vocabulary',gs,vs,vs,'Соедините каждую карточку с её значением.',ru('Используйте все карточки по одному разу.'),g,b)
 t.update(type='matching_pairs',left_items=[dict(id=f'l{i}',**wc(w)) for i,(w,r) in enumerate(rows)],right_items=[dict(id=f'r{i}',**ru(r)) for i,(w,r) in reversed(list(enumerate(rows)))],correct_pairs=[dict(left_id=f'l{i}',right_id=f'r{i}',assessed_vocabulary_ids=[w]) for i,(w,r) in enumerate(rows)])

def order(s,gs,vs,av,ins,ts,f,p,g,b):
 t=base(s,'sentence_building',gs,vs,av,ins,ru('Нажимайте на карточки в нужном порядке.'),g,b); tokens=[dict(id=f't{i}',**fr(f,p)) for i,(f,p) in enumerate(ts)]
 t.update(type='word_order',tokens=list(reversed(tokens)),accepted_orders=[[x['id'] for x in tokens]],completed_phrases=[dict(fr=f,transcription_ru=p)])

def fill(s,gs,vs,av,ins,bef,bp,aft,ap,cs,a,f,p,g,b):
 t=base(s,'vocabulary',gs,vs,av,ins,ru('Выберите одну карточку для пропуска.'),g,b)
 t.update(type='fill_blank',input_mode='choice',text_before=bef,text_before_transcription_ru=bp,text_after=aft,text_after_transcription_ru=ap,choices=opts(cs),correct_choice_id=f'c{a}',completed_phrases=[dict(fr=f,transcription_ru=p)])

 return t

def page(s,blocks):
 s['public_page']=dict(slug=s['id'].lower().replace('_','-'),summary=s['description'],seo_title=s['title']+' — французский с нуля',seo_description=s['description'],explanation_blocks=[dict(heading=h,paragraphs=ps,examples=es) for h,ps,es in blocks])

def addword(i,key,f,r,p,e,n,reviews):
 W[i]=dict(id=i,lexeme_key=key,fr=f,ru=[r],transcription_ru=p,example=e,review_items=reviews);FIRST[i]=n
addword('formal-name-question','fr:comment-vous-appelez-vous:formal-name-question','comment vous appelez-vous ?','Как вас зовут?','кома(н) ву заплэ ву́?',ex('Comment vous appelez-vous ?','Как вас зовут?','кома(н) ву заплэ ву́?'),1,[rev('formal-name-meaning',fr('Comment vous appelez-vous ?','кома(н) ву заплэ ву́?'),['Сколько вам лет?','Как вас зовут?','Где вы живёте?'],1,'Это вопрос об имени при обращении на «вы».','Правильный смысл — «Как вас зовут?», а не вопрос о возрасте или городе.'),rev('formal-name-use',ru('При первом вежливом знакомстве вы обращаетесь к человеку на «вы». Как спросить его имя?'),[wc('comment-tu-tappelles'),fr('Comment vous appelez-vous ?','кома(н) ву заплэ ву́?'),wc('merci')],1,'Выбран вопрос об имени с обращением на «вы».','Выберите вежливый вопрос на «вы»; неформальный вопрос на «ты» и благодарность не подходят.')])
addword('prenom','fr:prenom:given-name','le prénom','личное имя (не фамилия)','лё прэно́(н)',ex('Prénom : Mila.','Имя: Мила.','прэно(н) : мила́'),1,[rev('prenom-meaning',fr('Le prénom','лё прэно́(н)'),['Фамилия','Номер','Личное имя'],2,'Это личное имя в отличие от фамилии.','Здесь значение — личное имя; фамилия и номер обозначаются иначе.'),rev('prenom-use',ru('В анкете отдельные поля для имени и фамилии. Куда вписать личное имя Мила?'),[wc('nom-family-name'),fr('Prénom','прэно́(н)'),wc('numero')],1,'Для личного имени подходит это поле.','Нужно поле личного имени; фамилия и номер — другие данные.')])
addword('age-question','fr:quel-age-avez-vous:formal-age-question','quel âge avez-vous ?','Сколько вам лет?','кэль аж авэ ву́?',ex('Quel âge avez-vous ?','Сколько вам лет?','кэль аж авэ ву́?'),2,[rev('age-question-meaning',fr('Quel âge avez-vous ?','кэль аж авэ ву́?'),['Как вас зовут?','Сколько вам лет?','Назовите по буквам.'],1,'Вопрос относится к возрасту.','Спрашивают «Сколько вам лет?», а не имя или написание.'),rev('age-question-use',ru('Собеседник уже назвал имя. Теперь нужно узнать его возраст. Какой вопрос выбрать?'),[wc('formal-name-question'),fr('Quel âge avez-vous ?','кэль аж авэ ву́?'),wc('repetez')],1,'Выбран вопрос о возрасте.','Нужен возраст; повтор вопроса об имени или просьба повторить этого не спрашивают.')])
addword('jai-possession','fr:jai:possession','j’ai','у меня есть (о наличии вещи)','жэ',ex('J’ai un sac.','У меня есть сумка.','жэ э(н) са́к'),2,[rev('jai-possession-meaning',fr('J’ai un sac.','жэ э(н) са́к'),['Это сумка.','У меня есть сумка.','Сумку, пожалуйста.'],1,'Говорящий сообщает, что у него есть сумка.','Это сообщение о наличии вещи, а не указание на неё или просьба.'),rev('jai-possession-use',ru('Вы хотите сообщить, что у вас есть сумка. Выберите реплику о наличии вещи.'),[fr('C’est un sac.','сэт э(н) са́к'),fr('Un sac, s’il vous plaît.','э(н) сак, силь ву плэ́'),fr('J’ai un sac.','жэ э(н) са́к')],2,'Реплика сообщает о вашей вещи.','Нужно «У меня есть сумка»; указание и просьба имеют другой смысл.')])
addword('origin-question','fr:dou-venez-vous:city-origin-question','d’où venez-vous ?','Откуда вы? (при знакомстве)','ду вёнэ ву́?',ex('D’où venez-vous ?','Откуда вы?','ду вёнэ ву́?'),3,[rev('origin-question-meaning',fr('D’où venez-vous ?','ду вёнэ ву́?'),['Откуда вы?','Как вас зовут?','Сколько вам лет?'],0,'При знакомстве этот вопрос спрашивает, откуда человек.','Правильный смысл — «Откуда вы?», а не имя или возраст.'),rev('origin-question-use',ru('Вы знакомитесь с участником встречи и хотите спросить, откуда он. Выберите вопрос.'),[wc('age-question'),wc('formal-name-question'),fr('D’où venez-vous ?','ду вёнэ ву́?')],2,'Вопрос относится к происхождению в контексте знакомства.','Нужен вопрос «Откуда вы?»; другие вопросы касаются возраста и имени.')])
addword('je-suis-de','fr:je-suis-de:city-origin','je suis de','Я из (перед названием города)','жё сюи дё',ex('Je suis de Paris.','Я из Парижа.','жё сюи дё пари́'),3,[rev('je-suis-de-meaning',fr('Je suis de Paris.','жё сюи дё пари́'),['Я живу в Париже.','Я из Парижа.','Меня зовут Мила.'],1,'Образец сообщает, откуда человек.','Это «Я из Парижа»; место жительства отдельно не сообщено.'),rev('je-suis-de-use',ru('Ваш город происхождения — Лион. Как сказать, что вы из Лиона?'),[fr('Je suis de Lyon.','жё сюи дё льо́(н)'),fr('Je suis de Paris.','жё сюи дё пари́'),fr('Je m’appelle Mila.','жё мапэль мила́')],0,'Вы назвали Лион после изученного начала о происхождении.','Нужно назвать Лион в образце «Я из»; другой город и сообщение имени не подходят.')])
addword('residence-question','fr:ou-habitez-vous:city-residence-question','où habitez-vous ?','Где вы живёте?','у абитэ ву́?',ex('Où habitez-vous ?','Где вы живёте?','у абитэ ву́?'),4,[rev('residence-question-meaning',fr('Où habitez-vous ?','у абитэ ву́?'),['Откуда вы?','Где вы живёте?','Сколько вам лет?'],1,'Спрашивают о месте жительства.','Нужен смысл «Где вы живёте?», а не происхождение или возраст.'),rev('residence-question-use',ru('Вы уже знаете, откуда человек, и хотите уточнить, где он живёт сейчас. Что спросить?'),[wc('origin-question'),fr('Où habitez-vous ?','у абитэ ву́?'),wc('age-question')],1,'Вопрос относится именно к месту жительства.','Выберите вопрос о месте жительства; происхождение и возраст — другие сведения.')])
addword('jhabite-a','fr:jhabite-a:city-residence','j’habite à','Я живу в (перед названием города)','жабит а',ex('J’habite à Lyon.','Я живу в Лионе.','жабит а льо́(н)'),4,[rev('jhabite-a-meaning',fr('J’habite à Lyon.','жабит а льо́(н)'),['Я из Лиона.','Я живу в Париже.','Я живу в Лионе.'],2,'Речь о месте жительства в Лионе.','Это «Я живу в Лионе»: не путайте город и тип сведений.'),rev('jhabite-a-use',ru('Вы из Парижа, но живёте в Лионе. Как сообщить именно место жительства?'),[fr('J’habite à Paris.','жабит а пари́'),fr('J’habite à Lyon.','жабит а льо́(н)'),fr('Je suis de Lyon.','жё сюи дё льо́(н)')],1,'Реплика сообщает место жительства в Лионе.','Нужен город Лион в образце о проживании; происхождение и проживание в Париже не соответствуют ситуации.')])

def grammar(t):
 t['skill']='grammar'
 return t

